"""Retire the one reconciled old SDK object on the original allocation owner."""

import argparse
import base64
import hashlib
import json
import os
import stat
import subprocess
import tempfile
import types
import uuid
from pathlib import Path


HELPER_SHA = 'a2272c1061df54b73cbd019d835fc1fe1c2385b1936f8f44bbe75254da5cb8db'
HELPER = ''
AUDIT = ''


def require(value, message):
    if not value:
        raise RuntimeError(message)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ('run', 'pool', 'volume', 'segment'):
        parser.add_argument('--' + name, type=uuid.UUID, required=True)
    parser.add_argument('--manifest', type=Path, required=True)
    parser.add_argument('--outer-sha', required=True)
    args = parser.parse_args()
    run, pool = args.run.hex, args.pool
    require(args.manifest.is_absolute() and args.manifest.resolve() == args.manifest
            and args.manifest.name == 'manifest.json'
            and args.manifest.parent.parent == Path('/root/aenv-pmem')
            and args.manifest.parent.name.startswith('lower-pack-'), 'Unexpected owner manifest path')
    require(os.geteuid() == 0 and os.uname().nodename.split('.')[0] == 'agent1', 'M only')
    audit = types.ModuleType('takeover_readonly')
    exec(compile(base64.b64decode(AUDIT, validate=True), audit.__name__, 'exec'), audit.__dict__)
    obmm = audit.query_obmm(args.volume, args.segment)
    require(all(obmm.get(key, {}).get('status') == 'absent' for key in ('volume', 'segment')),
            'Old owner volume and local pool segment must both be absent')
    regions = audit.named_shmdevs('aenv_' + pool.hex)
    require(not regions['matches'] and not regions['truncated'] and not regions['unreadable'],
            'Owner-side old object references or scan errors appeared')
    require(not audit.inspect_processes([])['roles'], 'Owner runtime or Provider is active')
    path = Path('/var/lib/aenv-ub-sdk') / ('run-' + run) / 'state/sdk.json'
    journal = json.loads(audit.read_bytes(path, 128 * 1024))
    require(journal.get('run') == run and journal.get('node') == 'agent1' and
            set(journal['pools']) == {str(pool)}, 'Old owner SDK journal differs')
    record = journal['pools'][str(pool)]
    require(record.get('allocationOwner') is True and record.get('phase') == 'READY' and
            record['descriptor'].get('objectName') == 'aenv_' + pool.hex, 'Old object provenance differs')

    prepared = audit.read_bytes(args.manifest, 2 * 1024 * 1024)
    manifest = json.loads(prepared)
    require(manifest['document']['fileBytes'] == (1 << 30) and
            manifest['document']['layerDigest'] ==
            'sha256:' + args.outer_sha,
            'Prepared owner image metadata differs')
    print(json.dumps({'ownerManifest': str(args.manifest),
                      'manifestFileSha256': hashlib.sha256(prepared).hexdigest(),
                      'manifestDigest': manifest['sha256'], 'bytes': len(prepared)}), flush=True)

    payload = base64.b64decode(HELPER, validate=True).replace(b'@RUN@', run.encode('ascii'))
    payload = payload.replace(b'@OBJECT@', pool.hex.encode('ascii'))
    require(hashlib.sha256(payload).hexdigest() == HELPER_SHA, 'Owner helper differs')
    root = Path('/opt/aenv')
    info = root.lstat()
    require(root.resolve() == root and stat.S_ISDIR(info.st_mode) and info.st_uid == 0
            and not info.st_mode & 0o022, 'Unexpected adapter parent ownership or mode')
    receipt_dir = Path('/home/jwk/aenv-reclaim')
    if not os.path.lexists(receipt_dir):
        receipt_dir.mkdir(mode=0o700)
        os.chown(receipt_dir, 1204, 1205)
    info = receipt_dir.lstat()
    require(receipt_dir.resolve() == receipt_dir and stat.S_ISDIR(info.st_mode)
            and (info.st_uid, info.st_gid, stat.S_IMODE(info.st_mode)) == (1204, 1205, 0o700),
            'Unexpected receipt directory ownership or mode')
    name_prefix = 'reclaim-' + run[:8]
    receipt = receipt_dir / (name_prefix + '-unified.jsonl')
    for name in (name_prefix + '.jsonl', receipt.name):
        require(not os.path.lexists(receipt_dir / name), 'Prior SDK deletion receipt requires reconciliation')
    destination = Path(tempfile.mkdtemp(prefix='relay-' + name_prefix + '-', dir=root))
    destination.chmod(0o755)
    script = destination / 'reclaim_b5_object.py'
    with script.open('xb') as stream:
        stream.write(payload)
    script.chmod(0o644)
    return subprocess.run(['/usr/sbin/runuser', '-u', 'jwk', '--', '/usr/bin/python3', '-I', '-B', str(script),
                           '--execute', '--receipt', str(receipt)],
                          check=False).returncode


if __name__ == '__main__':
    raise SystemExit(main())
